// One item per PDF attachment, from either the inbox or the test form.
// Non-PDF attachments (signatures, logos) are ignored.
const out = [];
$input.all().forEach((item, i) => {
  const j = item.json || {};
  const rawFrom = String(j.from ?? j['Sender email (optional)'] ?? '');
  const sender = (rawFrom.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [''])[0].toLowerCase();
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const isPdf = String(bin.mimeType || '').includes('pdf') || /\.pdf$/i.test(bin.fileName || '');
    if (!isPdf) continue;
    out.push({
      json: {
        source: j.subject !== undefined ? 'email' : 'form',
        subject: j.subject || '',
        sender,
        pdfName: bin.fileName || `${key}.pdf`,
        received: new Date().toISOString(),
      },
      binary: { data: bin },
      pairedItem: { item: i },
    });
  }
});
return out;

// Builds one Claude request per PDF. The PDF is sent as a document, so the model reads
// the actual pages (scans, rotated faxes, handwriting) instead of extracted text.
// The model is told to answer only through the tool, so the answer follows the schema below.
// (Newer models don't accept a forced tool_choice; a missing tool call is caught and flagged downstream.)
const MODEL = 'claude-sonnet-5-5';

const address = { type: 'object', properties: {
  name: { type: 'string' }, line1: { type: 'string' }, line2: { type: 'string' },
  city: { type: 'string' }, state: { type: 'string' }, postal_code: { type: 'string' }, country: { type: 'string' } } };

const schema = {
  type: 'object',
  required: ['is_purchase_order', 'lines', 'uncertain_fields'],
  properties: {
    is_purchase_order: { type: 'boolean', description: 'false for quotes, invoices, statements or anything that is not an order' },
    po_number: { type: 'string' },
    order_date: { type: 'string', description: 'YYYY-MM-DD' },
    customer_name: { type: 'string', description: 'the buying company' },
    customer_email: { type: 'string' },
    bill_to: address,
    ship_to: address,
    requested_ship_date: { type: 'string', description: 'YYYY-MM-DD' },
    shipping_method: { type: 'string' },
    carrier_account: { type: 'string', description: 'third-party carrier account number if given (UPS, FedEx, etc.)' },
    notes: { type: 'string', description: 'delivery or handling instructions' },
    tax_exempt_id: { type: 'string', description: 'sales tax exemption certificate or ID number if printed (schools, districts, public bodies)' },
    payment_terms: { type: 'string', description: 'payment terms as written, e.g. Net 30' },
    lines: { type: 'array', items: { type: 'object', required: ['customer_part', 'quantity'], properties: {
      line_no: { type: 'integer' },
      customer_part: { type: 'string', description: 'part or item number exactly as written on the PO' },
      description: { type: 'string' },
      quantity: { type: 'number' },
      uom: { type: 'string', description: 'unit of measure as written, e.g. EA, CS, BX, FT' },
      unit_price: { type: 'number' },
      requested_date: { type: 'string', description: 'YYYY-MM-DD' } } } },
    uncertain_fields: { type: 'array', items: { type: 'string' },
      description: 'every field you could not read clearly or had to infer, e.g. "lines[2].quantity: handwritten, 7 or 1"' },
  },
};

const PROMPT = `Read this purchase order and record it by calling the record_purchase_order tool exactly once. Do not answer in plain text.
Rules:
- Copy values exactly as printed. Never invent a value: leave a field out if it is not on the document.
- Ignore cover sheets, fax headers, terms and conditions pages.
- Pages may be scanned, rotated or handwritten. If something is hard to read, give your best reading AND list it in uncertain_fields.
- Dates on US documents are MM/DD/YYYY; do not list them as uncertain for that reason alone. Do not list routine choices (which address line a value went on) as uncertain. uncertain_fields is only for values you recorded but could not read clearly; do not list page orientation, scan quality in general, or a value that is simply not printed.
- Quantities and prices are numbers without currency symbols. Dates are YYYY-MM-DD.
- If the document is not a purchase order, set is_purchase_order to false and return an empty lines list.`;

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({
    json: {
      ...items[i].json,
      body: {
        model: MODEL,
        max_tokens: 4096,
        tools: [{ name: 'record_purchase_order', description: 'Record the purchase order fields', input_schema: schema }],
        tool_choice: { type: 'auto' },
        messages: [{ role: 'user', content: [
          { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } },
          { type: 'text', text: PROMPT },
        ] }],
      },
    },
    pairedItem: { item: i },
  });
}
return out;

// Checks every extracted order against your reference data and writes plain-language flags.
// Nothing is guessed: if a value can't be matched, the order is marked "review".
const PRICE_TOLERANCE = 0.02; // 2% difference allowed between PO price and list price

const files = $('Build extraction request').all().map(i => i.json);
const replies = $('Read PO with Claude').all().map(i => i.json);
const customers = $('Load customers').all().map(i => i.json).filter(r => r.customer_id);
const catalog = $('Load items').all().map(i => i.json).filter(r => r.sku);

const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const dist = (a, b) => { // Levenshtein distance for "closest match" hints
  const m = a.length, n = b.length; const d = Array.from({ length: m + 1 }, (_, i) => [i, ...Array(n).fill(0)]);
  for (let j = 1; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) for (let j = 1; j <= n; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[m][n];
};
// Units written in words on POs ("each", "box", "pad") mean the same as catalog codes (EA, BX, PD).
const UNIT = { each: 'ea', ea: 'ea', box: 'bx', bx: 'bx', case: 'cs', cs: 'cs', pack: 'pk', pk: 'pk', pkg: 'pk', pad: 'pd', pd: 'pd',
  set: 'st', st: 'st', roll: 'rl', rl: 'rl', can: 'cn', cn: 'cn', dozen: 'dz', dz: 'dz', ream: 'rm', rm: 'rm' };
const unit = u => { const k = norm(u).replace(/s$/, ''); return UNIT[k] || UNIT[norm(u)] || norm(u); };
const domainOf = e => (String(e || '').split('@')[1] || '').toLowerCase();

const out = [];
replies.forEach((reply, idx) => {
  const file = files[idx] || {};
  const tool = (reply.content || []).find(c => c.type === 'tool_use');
  const po = tool?.input;
  const base = { received: file.received, source: file.source, sender: file.sender, pdfName: file.pdfName };
  if (!po) { out.push({ json: { ...base, status: 'review', flags: ['the AI could not read this PDF; check it by hand'], lines: [] } }); return; }
  if (po.is_purchase_order === false) return; // quotes, invoices etc. are skipped

  const flags = [];
  if (!po.po_number) flags.push('no PO number found');

  // Customer: email domain first, then company name.
  const domains = [domainOf(file.sender), domainOf(po.customer_email)].filter(Boolean);
  let customer = customers.find(c => c.email_domain && domains.includes(String(c.email_domain).toLowerCase()));
  if (!customer && po.customer_name) {
    const n = norm(po.customer_name);
    customer = customers.find(c => norm(c.name) && (n.includes(norm(c.name)) || norm(c.name).includes(n)));
  }
  if (!customer) flags.push(`customer not recognised: "${po.customer_name || file.sender || 'unknown'}"`);
  if (!po.ship_to?.line1) flags.push('no ship-to address found');

  const lines = (po.lines || []).map((l, k) => {
    const no = l.line_no || k + 1;
    const part = norm(l.customer_part);
    const options = catalog.filter(r => !r.customer_id || !customer || String(r.customer_id) === String(customer.customer_id));
    // A blank part number never matches anything (catalog rows often have a blank customer_part).
    const hit = !part ? null : options.find(r => norm(r.customer_part) && norm(r.customer_part) === part) || options.find(r => norm(r.sku) === part);
    if (!part) {
      flags.push(`line ${no}: no part number on the PO` + (l.description ? ` ("${l.description}")` : '') + '; pick the item by hand');
    } else if (!hit) {
      // Compare only against codes that exist: an empty customer_part must not count as a near match.
      const closest = options.map(r => [r, Math.min(...[r.sku, r.customer_part].map(norm).filter(Boolean).map(c => dist(part, c)))]).sort((a, b) => a[1] - b[1])[0];
      flags.push(`line ${no}: part ${l.customer_part || '(blank)'} not recognised` + (closest && closest[1] <= 3 ? `; closest match ${closest[0].sku}` : ''));
    } else {
      if (l.uom && hit.uom && unit(l.uom) !== unit(hit.uom)) flags.push(`line ${no}: unit ${l.uom} on PO, ${hit.uom} in catalog`);
      const list = Number(hit.price);
      if (l.unit_price != null && list > 0 && Math.abs(l.unit_price - list) / list > PRICE_TOLERANCE)
        flags.push(`line ${no}: price ${l.unit_price} on PO vs ${list} list`);
    }
    if (!(l.quantity > 0)) flags.push(`line ${no}: quantity missing or zero`);
    return { line_no: no, sku: hit?.sku || '', customer_part: l.customer_part || '', description: l.description || hit?.description || '',
             quantity: l.quantity ?? '', uom: l.uom || hit?.uom || '', unit_price: l.unit_price ?? hit?.price ?? '', requested_date: l.requested_date || po.requested_ship_date || '' };
  });
  if (!lines.length) flags.push('no order lines found');
  for (const f of po.uncertain_fields || []) flags.push(`unclear on the document: ${f}`);

  out.push({ json: { ...base, poNumber: po.po_number || '', customerName: customer?.name || po.customer_name || '', customerId: customer?.customer_id || '',
    shipTo: po.ship_to || {}, carrierAccount: po.carrier_account || '', shippingMethod: po.shipping_method || '', notes: po.notes || '',
    orderDate: po.order_date || '', taxExemptId: po.tax_exempt_id || '', paymentTerms: po.payment_terms || '',
    lines, lineCount: lines.length, flags, status: flags.length ? 'review' : 'ok' } });
});
return out;

// One CSV per order in the column order your ERP import expects. Edit COLUMNS to match it.
const COLUMNS = ['po_number', 'customer_id', 'ship_to_name', 'ship_to_address', 'ship_to_city', 'ship_to_state', 'ship_to_postal_code',
  'line_no', 'sku', 'customer_part', 'description', 'quantity', 'uom', 'unit_price', 'requested_date', 'shipping_method', 'carrier_account', 'notes', 'order_date', 'tax_exempt_id', 'payment_terms', 'needs_review'];
const esc = v => { v = v == null ? '' : String(v); return /[",\n\r]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v; };
const safe = s => String(s || '').replace(/[^A-Za-z0-9_-]+/g, '-').slice(0, 40);

const out = [];
for (const [i, item] of $input.all().entries()) {
  const o = item.json; const s = o.shipTo || {};
  const rows = o.lines.map(l => ({
    po_number: o.poNumber, customer_id: o.customerId, ship_to_name: s.name, ship_to_address: [s.line1, s.line2].filter(Boolean).join(', '),
    ship_to_city: s.city, ship_to_state: s.state, ship_to_postal_code: s.postal_code, ...l,
    shipping_method: o.shippingMethod, carrier_account: o.carrierAccount, notes: o.notes,
    order_date: o.orderDate, tax_exempt_id: o.taxExemptId, payment_terms: o.paymentTerms, needs_review: o.status === 'review' ? 'yes' : 'no' }));
  const csv = [COLUMNS.join(','), ...rows.map(r => COLUMNS.map(c => esc(r[c])).join(','))].join('\r\n') + '\r\n';
  const fileName = `${o.status === 'review' ? 'REVIEW_' : ''}PO_${safe(o.poNumber) || 'NO-PO'}_${safe(o.customerId) || 'UNKNOWN'}_${String(o.received || '').slice(0, 10)}.csv`;
  const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), fileName, 'text/csv') };
  out.push({ json: { ...o, fileName }, binary, pairedItem: { item: i } });
}
return out;

